pub fn get(id: &str) -> Option<&'static G> { W2B.binary_search_by(|g| g.id.cmp(id)).ok().map(|i| &W2B[i]).or_else(|| GATE.binary_search_by(|g| g.id.cmp(id)).ok().map(|i| &GATE[i])) } // + intraday wave 2b
/// First date with real opens for each US index (measured: stale opens equal the prior close on 13-92% of days before these years).
pub fn real_open_from(ticker: &str) -> Option<&'static str> { match ticker { "NDX" => Some("2001-01-01"), "SPX" => Some("2014-01-01"), "DJI" => Some("2016-01-01"), _ => None } }
#[cfg(test)]
mod tests {
    #[test] fn w2b_sorted_and_found() { assert!(super::W2B.windows(2).all(|w| w[0].id < w[1].id)); assert_eq!(super::get("acbff_c40").unwrap().verdict, "unverified"); assert_eq!(super::get("jchr1_lizard_long").unwrap().verdict, "withheld"); } // intraday wave 2b
    #[test] fn sorted_and_found() { assert!(super::GATE.windows(2).all(|w| w[0].id < w[1].id)); assert!(super::get(super::GATE[0].id).is_some()); }
    #[test]
    fn radge_plain_research_keeps_symbol_and_open_guards() {
        let g=super::get("radge_oc_long").unwrap();
        assert_eq!(g.verdict,"unverified");
        assert!(g.clamp_open);
        assert_eq!(g.allowed,Some(&["NIFTY 50","SPX"][..]));
        assert_eq!(super::real_open_from("SPX"),Some("2014-01-01"));
        assert_eq!(super::get("radge_oc_long_stop").unwrap().verdict,"withheld");
    }
}
